    /// <summary>
    /// Sends Firebase Authentication SMS to the specified phone number. Works only when received a code of the type authenticationCodeTypeFirebaseAndroid or authenticationCodeTypeFirebaseIos
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SendPhoneNumberFirebaseSmsAsync(string token = default)
    {

           using var activity =  StartCallActivity("SendPhoneNumberFirebaseSmsAsync", typeof(SendPhoneNumberFirebaseSms).FullName ?? "SendPhoneNumberFirebaseSmsAsync");

           try
           {
             return client.SendPhoneNumberFirebaseSmsAsync(token);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
